"""Real dawtool fixtures plus explicitly synthetic ALS regressions."""
import gzip
import hashlib
import math
import tempfile
import unittest
from pathlib import Path

import core

FIXTURES = Path(__file__).parent / "fixtures" / "als"


def event(beat, value, tag="FloatEvent", extra=""):
    return f'<{tag} Time="{beat}" Value="{value}" {extra}/>'


def synthetic(tempo_events="", meter_events="", manual=100, meter=201,
              track="MasterTrack", legacy=False):
    """Synthetic, not claimed to be generated by Live. IDs are deliberately distinct."""
    def parameter(name, value, target, events):
        initial = f'<Manual Value="{value}"/>' if value is not None else ""
        old = f'<ArrangerAutomation><Events>{events}</Events></ArrangerAutomation>' if legacy else ""
        return f'<{name}>{initial}<AutomationTarget Id="{target}"/>{old}</{name}>'
    def envelope(target, events):
        return (f'<AutomationEnvelope><EnvelopeTarget><PointeeId Value="{target}"/>'
                f'</EnvelopeTarget><Automation><Events>{events}</Events></Automation></AutomationEnvelope>')
    envelopes = "" if legacy else ('<AutomationEnvelopes><Envelopes>' +
        envelope(999, event(0, 999)) + envelope(42, tempo_events) +
        envelope(7, meter_events) + '</Envelopes></AutomationEnvelopes>')
    return ('<Ableton><LiveSet>' + f'<{track}><DeviceChain><Mixer>' +
            parameter("Tempo", manual, 42, tempo_events) +
            parameter("TimeSignature", meter, 7, meter_events) +
            f'</Mixer></DeviceChain>{envelopes}</{track}></LiveSet></Ableton>')


class ALSFixtureTests(unittest.TestCase):
    def test_fixture_bytes_match_pinned_public_sources(self):
        hashes = {
            "example-140.als": "729d6dc738183a17c2a8d2892ecdacbd08427daecfe37680b297ca75ed07703a",
            "automation.als": "0460dffb04fa2137a2620fcaab7dd420b84a80c5bb2ccbabe657a213a0253c41",
            "L12-automation.als": "5756a430081aad79c4fac6d4c1d3b0b22f4cf105a3d68971cf17e00a4f1ff11a",
            "live8-patch-markers-noauto.als": "7d7b8ae5d82855e823e182b22cb35530991e0210e3cc334b92ec6e80d60d0e36",
            "live9-patch-markers-noauto.als": "d41f5ddf6cee45a6a53843213c5adb249774faab3a4b1732b60b33dbe439b579",
            "automation-pathological.als": "56180f912625a9ebdb16544c9e60e6758fa027a3d6262932e9f1efcca174611f",
        }
        for name, expected in hashes.items():
            with self.subTest(name=name):
                self.assertEqual(hashlib.sha256((FIXTURES / name).read_bytes()).hexdigest(), expected)

    def test_real_vertical_jumps_are_zero_duration(self):
        tm = core.read_tempo_map(FIXTURES / "automation-pathological.als")
        self.assertEqual([p.bpm for p in tm.points[:2]], [120.760574, 120.699997])
        self.assertEqual([p.beat for p in tm.points[:2]], [0, 0])
        self.assertEqual([p.time for p in tm.points[:2]], [0, 0])
        self.assertAlmostEqual(tm.points[2].beat, 0.0700661317848817883)
        self.assertEqual(tm.points[2].bpm, 120.599998)
        self.assertAlmostEqual(tm.points[2].time, 60 * tm.points[2].beat / 120.699997)
        self.assertAlmostEqual(tm.points[-1].beat, 21.542576433982685)
        self.assertEqual(tm.points[-1].bpm, 147.658524)
        self.assertEqual([p.time for p in tm.points], sorted(p.time for p in tm.points))
        for p in tm.points:
            self.assertTrue(math.isfinite(p.time))
        for prev, cur in zip(tm.points, tm.points[1:]):
            if prev.beat == cur.beat:
                self.assertEqual(prev.time, cur.time)

    def test_real_live10_constant(self):
        tm = core.read_tempo_map(FIXTURES / "example-140.als")
        self.assertEqual([(p.beat, p.time, p.bpm, p.num, p.den, p.ramp) for p in tm.points],
                         [(0, 0, 140, 4, 4, False)])
        self.assertGreater(tm.project_end_beat, 9000)

    def test_real_live10_and_live12_ramps(self):
        for name in ("automation.als", "L12-automation.als"):
            with self.subTest(name=name):
                tm = core.read_tempo_map(FIXTURES / name)
                self.assertEqual([p.beat for p in tm.points], [0, 4, 8, 12])
                self.assertEqual([p.bpm for p in tm.points], [60, 60, 120, 200])
                self.assertEqual([p.ramp for p in tm.points], [False, True, True, False])
                self.assertAlmostEqual(tm.points[1].time, 4)
                self.assertAlmostEqual(tm.points[2].time, 4 + 4 * math.log(2))
                self.assertAlmostEqual(tm.points[3].time, 4 + 4 * math.log(2) + 3 * math.log(5/3))
                self.assertTrue(any("quantization" in w.lower() for w in tm.warnings))

    def test_real_live8_and_live9_sentinels(self):
        for name, bpm in (("live8-patch-markers-noauto.als", 95.3),
                          ("live9-patch-markers-noauto.als", 135)):
            with self.subTest(name=name):
                tm = core.read_tempo_map(FIXTURES / name)
                self.assertEqual([(p.beat, p.time, p.bpm, p.num, p.den) for p in tm.points],
                                 [(0, 0, bpm, 4, 4)])


class ALSSyntheticTests(unittest.TestCase):
    def read(self, xml):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "synthetic.als"
            path.write_bytes(gzip.compress(xml.encode(), mtime=0))
            return core.read_tempo_map(path)

    def test_progress_completes_for_manual_and_automated_maps(self):
        for xml in (synthetic(), synthetic(event(0, 60) + event(8, 120))):
            with tempfile.TemporaryDirectory() as tmp:
                path = Path(tmp) / "progress.als"
                path.write_bytes(gzip.compress(xml.encode(), mtime=0))
                progress = []
                core.read_tempo_map(path, progress.append)
                self.assertTrue(progress)
                self.assertEqual(progress[-1], 1)
                self.assertEqual(progress, sorted(progress))

    def test_manual_fallback_is_not_120(self):
        tm = self.read(synthetic(manual=97, meter=303, track="MainTrack"))
        self.assertEqual([(p.beat, p.time, p.bpm, p.num, p.den) for p in tm.points],
                         [(0, 0, 97, 7, 8)])

    def test_legacy_automation_overrides_manual(self):
        tm = self.read(synthetic(event(-63072000, 103), legacy=True))
        self.assertEqual(tm.points[0].bpm, 103)

    def test_missing_initial_event_holds_manual_until_first_breakpoint(self):
        tm = self.read(synthetic(event(4, 120) + event(8, 60), manual=90))
        self.assertEqual([p.beat for p in tm.points], [0, 4, 8])
        self.assertEqual([p.ramp for p in tm.points], [False, True, False])
        self.assertAlmostEqual(tm.points[1].time, 8/3)
        self.assertAlmostEqual(tm.points[2].time, 8/3 + 4 * math.log(2))

    def test_meter_only_breakpoints_split_ramp_and_extend_map(self):
        tm = self.read(synthetic(event(0, 60) + event(8, 120),
                                 event(-63072000, 200, "EnumEvent") +
                                 event(4, 303, "EnumEvent") + event(12, 201, "EnumEvent")))
        self.assertEqual([p.beat for p in tm.points], [0, 4, 8, 12])
        self.assertEqual([p.bpm for p in tm.points], [60, 90, 120, 120])
        self.assertEqual([(p.num, p.den) for p in tm.points], [(3, 4), (7, 8), (7, 8), (4, 4)])
        self.assertEqual([p.ramp for p in tm.points], [True, True, False, False])
        self.assertAlmostEqual(tm.points[1].time, 8 * math.log(1.5))
        self.assertAlmostEqual(tm.points[2].time, 8 * math.log(2))
        self.assertAlmostEqual(tm.points[3].time, 8 * math.log(2) + 2)
        self.assertEqual(tm.bar_beat(4), "3.1")

    def test_unsorted_events_and_multiple_negative_events(self):
        tm = self.read(synthetic(event(8, 120) + event(-1, 80) + event(4, 80) + event(-63072000, 70)))
        self.assertEqual([p.beat for p in tm.points], [0, 4, 8])
        self.assertEqual([p.bpm for p in tm.points], [80, 80, 120])
        self.assertAlmostEqual(tm.points[1].time, 3)

    def test_duplicate_beats_preserve_incoming_and_outgoing_jump(self):
        tm = self.read(synthetic(event(0, 60) + event(4, 120) + event(4, 90) + event(8, 90)))
        self.assertEqual([p.beat for p in tm.points], [0, 4, 4])
        self.assertEqual([p.bpm for p in tm.points], [60, 120, 90])
        self.assertAlmostEqual(tm.points[1].time, 4 * math.log(2))
        self.assertEqual(tm.points[1].time, tm.points[2].time)
        steps = core.approximate(tm, core.ExportOptions(min_bpm_change=0))
        self.assertEqual(steps[-1], (4, 90))
        self.assertTrue(all(math.isfinite(bpm) and bpm > 0 for _, bpm in steps))

    def test_beat_linear_export_preserves_integral_and_point_sampling(self):
        tm = self.read(synthetic(event(0, 60) + event(8, 120)))
        opt = core.ExportOptions(ramp_step=1, min_bpm_change=0)
        steps = core.approximate(tm, opt)
        elapsed = sum((q1-q0)*60/bpm for (q0, bpm), (q1, _) in zip(steps, steps[1:]))
        self.assertAlmostEqual(elapsed, 8 * math.log(2))
        opt.preserve_timing = False
        steps = core.approximate(tm, opt)
        self.assertEqual(steps[4], (4, 90))
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "tempo.mid"
            core.write_midi(tm, path, core.ExportOptions(ramp_step=0.25, min_bpm_change=0))
            midi = core.read_tempo_map(path)
            self.assertAlmostEqual(midi.points[-1].time, tm.points[-1].time, places=5)

    def test_reaper_time_linear_ramp_domain_is_unchanged(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "ramp.rpp"
            path.write_text('TEMPO 60 4 4\n<TEMPOENVEX\nPT 0 60 0 0\nPT 8 120 1 0\n>\n')
            tm = core.read_tempo_map(path)
            self.assertEqual(tm.points[-1].beat, 12)
            self.assertEqual(tm.points[-1].time, 8)
            steps = core.approximate(tm, core.ExportOptions(ramp_step=3, min_bpm_change=0))
            elapsed = sum((q1-q0)*60/bpm for (q0, bpm), (q1, _) in zip(steps, steps[1:]))
            self.assertAlmostEqual(elapsed, 8)

    def test_nonfinite_nonpositive_and_missing_values_are_errors(self):
        for value in ("nan", "inf", "0", "-1", "bad"):
            with self.subTest(value=value), self.assertRaises(core.ReaderError):
                self.read(synthetic(event(0, value)))
        for xml in (synthetic('<FloatEvent Time="0"/>'), synthetic(event("nan", 120)),
                    synthetic(manual=None), synthetic(meter=495), synthetic(meter=-1),
                    synthetic(meter=201.5)):
            with self.subTest(xml=xml), self.assertRaises(core.ReaderError):
                self.read(xml)

    def test_missing_automation_target_id_does_not_silently_ignore_envelope(self):
        xml = synthetic(event(0, 60) + event(8, 120)).replace('<AutomationTarget Id="42"/>', '<AutomationTarget/>')
        with self.assertRaisesRegex(core.ReaderError, "[Tt]arget"):
            self.read(xml)

    def test_ambiguous_or_damaged_matching_envelope_is_an_error(self):
        import xml.etree.ElementTree as ET
        import copy
        for duplicate in (True, False):
            root = ET.fromstring(synthetic(event(0, 60)))
            envelopes = root.find('./LiveSet/MasterTrack/AutomationEnvelopes/Envelopes')
            matching = list(envelopes)[1]
            if duplicate:
                envelopes.append(copy.deepcopy(matching))
            else:
                matching.remove(matching.find('Automation'))
            with self.subTest(duplicate=duplicate), self.assertRaises(core.ReaderError):
                self.read(ET.tostring(root, encoding='unicode'))

    def test_beat_zero_automation_overrides_sentinel_and_manual(self):
        tm = self.read(synthetic(event(-63072000, 80) + event(0, 90) + event(8, 90),
                                 event(-63072000, 201, 'EnumEvent') + event(0, 303, 'EnumEvent')))
        self.assertEqual([(p.beat, p.bpm, p.num, p.den) for p in tm.points], [(0, 90, 7, 8)])

    def test_curved_automation_is_rejected_not_silently_linearized(self):
        with self.assertRaisesRegex(core.ReaderError, "[Cc]urv"):
            self.read(synthetic(event(0, 60, extra='CurveControl1X="0.2" CurveControl1Y="0.8" CurveControl2X="0.8" CurveControl2Y="0.2"') + event(8, 120)))

    def test_missing_mixer_or_tempo_is_readable_error(self):
        for xml in ('<Ableton><LiveSet/></Ableton>',
                    '<Ableton><LiveSet><MainTrack><DeviceChain><Mixer/></DeviceChain></MainTrack></LiveSet></Ableton>'):
            with self.assertRaises(core.ReaderError):
                self.read(xml)

    def test_corrupt_compression_and_xml_are_readable_errors(self):
        valid = gzip.compress(synthetic().encode(), mtime=0)
        for data in (b'not gzip', valid[:-5], valid[:10] + b'\xff'*20 + valid[-8:], gzip.compress(b'<Ableton>')):
            with tempfile.TemporaryDirectory() as tmp:
                path = Path(tmp) / 'broken.als'
                path.write_bytes(data)
                with self.subTest(data=data[:20]), self.assertRaises(core.ReaderError):
                    core.read_tempo_map(path)


if __name__ == '__main__':
    unittest.main()
